  while(left>0){const l=new Date(t+OFF);const h=l.getUTCHours()+l.getUTCMinutes()/60+l.getUTCSeconds()/3600;
    if(h<START){t+=(START-h)*3600e3;continue;}if(h>=END){t+=(24-h+START)*3600e3;continue;}
