const MAKER_NAME=/candle|كاندل|شموع|شمع/i;
const MAKER_TXT=/(مصنع|تصنيع|يصنع|تصنع|صانع|منتج|مصبوب|يدوي)[^.؛،\n]{0,25}(شمع|شموع)|(شمع|شموع)[^.؛،\n]{0,15}(يدوي|مصبوب|صويا)|candle ?(maker|brand|studio|factory|shop)|hand-?poured/i;
